 const tot=live.reduce((a,l)=>a+l.principal,0)+x.principal;if(L.max_total>0&&tot>L.max_total)W.push("Total pokok nasabah menjadi Rp "+fm(tot)+" (batas Rp "+fm(L.max_total)+")");
