// ===== v1.1.004: simulasi angsuran langsung di modal pengajuan, ajukan dari nasabah =====
function ajukanDari(id,cid){S.lpp=id;S.lpc=cid||null;mdOpen("lp","")}
function simWarn(P,r,n,m,d){const e=$("#sim-w");if(!e)return;const pt=($("#l-pty")||{}).value;let W=[];if(pt&&P>0&&Number.isInteger(n))W=loanWarns({party_id:pt,principal:P,tenor:n,interest_rate:r,interest_method:m,application_date:d},null);e.innerHTML=W.length?`<div class="warn" role="status"><b>Perhatian sebelum mengirim</b><ul>${W.map(w=>"<li>"+esc(w)+"</li>").join("")}</ul><span class="k">Pengajuan tetap bisa dikirim; tekan tombol dua kali untuk melanjutkan.</span></div>`:""}
function simLive(){try{const e=$("#sim");if(!e)return;const v=i=>($("#"+i)||{}).value||"",P=Math.round(+pn(v(LI("p")))||0),r=Number(String(jasaForm()).replace(",",".")),n=Number(v(LI("t"))),m=v(LI("m"))||"flat",d=v(LI("d"))||today();
 simWarn(P,r,n,m,d);{const fe=$("#sim-fee");if(fe)fe.innerHTML=feeInfoHtml(P,r,n,m,d)}if(!(P>0)||!Number.isFinite(r)||r<0||!Number.isInteger(n)||n<1||n>360){e.innerHTML=`<div class="k">Simulasi angsuran</div><p class="k">Isi pokok, jasa, dan tenor untuk melihat perkiraan angsuran.</p>`;return}
 const s=simulate(Object.assign({principal:P,rate:r,tenor:n,method:m,start:d},calcSet())),K=(k,x)=>`<div class="kv"><span class="k">${k}</span><b>${x}</b></div>`,f=s.schedule;
 e.innerHTML=`<div class="k">Simulasi angsuran (perkiraan, dihitung dari tanggal pengajuan)</div><div class="kvg">${K("Angsuran pertama",rp(s.first_installment))}${s.last_installment!==s.first_installment?K("Angsuran terakhir",rp(s.last_installment)):K("Tenor",n+" bulan")}${K("Total jasa",rp(s.total_interest))}${K("Total bayar",rp(s.total_payment))}${K("Jasa efektif / tahun",s.irr_effective_year.toFixed(2).replace(".",",")+"%")}</div><details class="sx"><summary>Jadwal angsuran <span class="stc">${f.length}</span></summary>${tbl(["Ke","Jatuh tempo","#Pokok","#Jasa","#Total"],f.map(x=>`<tr><td>${x.n}</td><td>${x.due_date}</td><td class="n">${rp(x.principal_due)}</td><td class="n">${rp(x.interest_due)}</td><td class="n">${rp(x.total_due)}</td></tr>`))}</details>`}catch(x){}}
